const $=s=>document.querySelector(s);const el={boot:$('#boot'),hero:$('#hero'),vsNum:$('#vs-num'),verdict:$('#verdict'),verdictTxt:$('#verdict-txt'),action:$('#action'),picks:$('#picks'),hist:$('#hist'),facts:$('#facts'),cv:$('#cv'),foot:$('#foot'),};let retry=0;async function boot(){try{const d=await fetch('/api/fin').then(r=>r.json());if(!d.ready){kick(2000);return;}render(d);loadHist();}catch(_){kick(3000);}}function kick(ms){if(retry++>40){el.boot.textContent='算不出来，刷新一下试试';return;}setTimeout(boot,ms);}function render(d){el.boot.hidden=true;el.hero.hidden=false;const v=+d.vs20;el.vsNum.textContent=(v>0?'+':'')+v.toFixed(2);const on=!!d.allow;el.verdict.className='verdict'+(on?' on':'');el.verdictTxt.textContent=on?'可以买':'再等等';if(on){el.action.innerHTML=`两只各买一半，<b>${d.hold_days} 天后卖出</b>，中途不看`;}else{const need=Math.abs(v)<d.gate?(d.gate-Math.abs(v)).toFixed(2):'—';el.action.innerHTML=`大盘还要再跌 <b>${need}%</b> 才到进场位置`;}el.picks.hidden=false;el.picks.innerHTML=(d.picks||[]).map(p=>`
    <article class="pick">
      <span class="tag">${esc(p.board)}</span>
      <div class="nm">${esc(p.name)}</div>
      <div class="cd">${esc(p.code)}</div>
      <div class="px">${(+p.price).toFixed(2)}<i>元</i></div>
    </article>`).join('');el.foot.innerHTML=`<span>${esc(d.asof)} 收盘</span>`+`<span>仓位各半 · 持有 ${d.hold_days} 天</span>`;}function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}async function loadHist(){let h;try{h=await fetch('/api/fin/history').then(r=>r.json());}catch(_){return;}if(!h||!h.curve||!h.curve.length)return;el.hist.hidden=false;const s=h.stat||{};const ys=h.yearly||Object.entries(h.yearly||{}).map(([k,v])=>({k,v}));const vals=h.yearly?Object.values(h.yearly):[];const worst=vals.length?Math.min(...vals):0;el.facts.innerHTML=`
    <div><b>${s.ann>0?'+':''}${(+s.ann).toFixed(1)}%</b>每年</div>
    <div><b>${(+s.mdd).toFixed(1)}%</b>最大回撤</div>
    <div><b>${worst.toFixed(0)}%</b>最差一年</div>
    <div><b>${(+s.sharpe).toFixed(2)}</b>夏普</div>`;draw(h.curve);}function draw(pts){const cv=el.cv,dpr=window.devicePixelRatio||1;const W=cv.clientWidth,H=cv.clientHeight||150;cv.width=W*dpr;cv.height=H*dpr;const g=cv.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,W,H);const pad={l:3,r:3,t:12,b:18};const w=W-pad.l-pad.r,h=H-pad.t-pad.b;let t0=Date.parse(pts[0][0]),t1=Date.parse(pts[pts.length-1][0]);let lo=Infinity,hi=-Infinity;for(const[,v]of pts){if(v<lo)lo=v;if(v>hi)hi=v;}lo=Math.min(lo,1);hi=Math.max(hi,1);const span=hi-lo||1;lo-=span*0.08;hi+=span*0.08;const X=t=>pad.l+w*(t-t0)/(t1-t0);const Y=v=>pad.t+h-h*(v-lo)/(hi-lo);g.strokeStyle='#e7e5e4';g.setLineDash([3,4]);g.lineWidth=1;g.beginPath();g.moveTo(pad.l,Y(1));g.lineTo(pad.l+w,Y(1));g.stroke();g.setLineDash([]);const grad=g.createLinearGradient(0,pad.t,0,pad.t+h);grad.addColorStop(0,'rgba(37,99,235,.13)');grad.addColorStop(1,'rgba(37,99,235,0)');g.beginPath();pts.forEach(([d,v],i)=>{const x=X(Date.parse(d)),y=Y(v);i?g.lineTo(x,y):g.moveTo(x,y);});g.lineTo(X(t1),pad.t+h);g.lineTo(X(t0),pad.t+h);g.closePath();g.fillStyle=grad;g.fill();g.beginPath();pts.forEach(([d,v],i)=>{const x=X(Date.parse(d)),y=Y(v);i?g.lineTo(x,y):g.moveTo(x,y);});g.strokeStyle='#2563eb';g.lineWidth=1.6;g.lineJoin='round';g.lineCap='round';g.stroke();g.font='10px -apple-system,BlinkMacSystemFont,sans-serif';g.fillStyle='#a8a29e';g.textBaseline='top';const y0=pts[0][0].slice(0,4),y1=pts[pts.length-1][0].slice(0,4);const mid=String(Math.round((+y0+ +y1)/2));[[y0,'left'],[mid,'center'],[y1,'right']].forEach(([y,al])=>{const i=pts.findIndex(p=>p[0].startsWith(y));if(i<0)return;const x=X(Date.parse(pts[i][0]));g.textAlign=al;g.fillText(y,x,pad.t+h+4);});}window.addEventListener('resize',()=>{fetch('/api/fin/history').then(r=>r.json()).then(h=>h&&h.curve&&draw(h.curve)).catch(()=>{});});boot();